   169  /* if @utf16 is prefix of @ascii (ignoring non-representable characters and upper-case conversion)
   170   * then reconstruct prefix from @utf16 and @ascii, append suffix from @ascii, fill it into @out
   171   * and returns length of bytes written into @out; otherwise returns zero */
   172  static size_t merge_utf16be_ascii(unsigned char *out, const unsigned char *utf16, const unsigned char *ascii, size_t len)
   173  {
   174          size_t o, a, u;
   175
   176          for (o = 0, a = 0, u = 0; u + 1 < len && a < len; o += 2, a++, u += 2) {
   177                  /* Surrogate pair with code point above U+FFFF */
   178                  if (utf16[u] >= 0xD8 && utf16[u] <= 0xDB && u + 3 < len &&
   179                      utf16[u + 2] >= 0xDC && utf16[u + 2] <= 0xDF) {
   180                          out[o++] = utf16[u++];
   181                          out[o++] = utf16[u++];
   182                  }
   183                  /* Value '_' is replacement for non-representable character */
   184                  if (ascii[a] == '_') {
   185                          out[o] = utf16[u];
   186                          out[o + 1] = utf16[u + 1];
   187                  } else if (utf16[u] == 0x00 && utf16[u + 1] == '_') {
   188                          out[o] = 0x00;
   189                          out[o + 1] = ascii[a];
   190                  } else if (utf16[u] == 0x00 && c_toupper(ascii[a]) == c_toupper(utf16[u + 1])) {
   191                          out[o] = 0x00;
   192                          out[o + 1] = c_isupper(ascii[a]) ? utf16[u + 1] : ascii[a];
   193                  } else {
   194                          return 0;
   195                  }
   196          }
   197
   198          for (; a < len; o += 2, a++) {
   199                  out[o] = 0x00;
   200                  out[o + 1] = ascii[a];
   201          }
   202
   203          return o;
   204  }
